  ('fc32748b-9907-554a-9b53-f70e0554f5aa', 'kWh_net', 'kWh', '1', 'natural_gas', 'derived from factor set si-2025-r4 (workbook conversion_to_gj)', '0.0036 / 0.0036 — the billed kWh is this set net kWh'),
  ('038416b1-9853-5e45-b828-ca5499b522a5', 'MWh', 'kWh_net', '1000', 'natural_gas', 'derived from factor set si-2025-r4 (workbook conversion_to_gj)', '3.6 / 0.0036'),
